using Astrea.BattleActions;
using Astrea.GameElements;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "DiceTargetCastStateJoystickAction", menuName = "Data/Battle/Actions/DiceTargetCastStateJoystickAction")]
public class DiceTargetCastStateJoystickAction : Action
{
	[SerializeField]
	private ActionInstanceReference actionInstanceReference;

	public override void OnStartState()
	{
		base.OnStartState();
		base.actionInstance.OnMouseExit();
		ActionFace actionFace = base.actionInstance.ActionFace;
		actionInstanceReference.SetValue(base.actionInstance);
		if (base.actionInstance is DiceInstance)
		{
			(base.actionInstance as DiceInstance).DiceMovement.StartFollowingMouseRotationAnimation();
		}
		ReferenceSingleton<InputManager>.Instance.MoveActionInstanceToDicePlacementCastAction(delegate
		{
			(actionFace.BattleAction as ChooseDiceAction).ActionSelected(actionFace.ModifiedActionValue);
			(actionInstanceReference.Value.ActionFace.BattleAction.GetDiceActionLogic(actionInstanceReference.Value.ActionFace.ModifiedActionValue) as DiceActionLogic_ChooseDice).OnChooseDiceStateEvent.Raise();
		});
		base.actionInstance.ActionDroppedOnBattleActionCastSpace();
		ReferenceSingleton<BattleHandler>.Instance.SetCurrentActionInstance(null);
	}

	public override void Execute(float d)
	{
	}
}
